    public String findBitmapByCardNumber(String cardNumber) {
        String normalizedCardNumber = normalizeCardNumber(cardNumber);

        if (normalizedCardNumber.length() < IIN_LENGTH) {
            return null;
        }

        String iin = normalizedCardNumber.substring(0, IIN_LENGTH);
        return bitmapByIin.get(iin);
    }


    public String getBitmapByCardNumber(String cardNumber) {
        return findBitmapByCardNumber(cardNumber);
    }


    public boolean supports(String cardNumber) {
        return findBitmapByCardNumber(cardNumber) != null;
    }

    private String normalizeCardNumber(String cardNumber) {
        if (cardNumber == null || cardNumber.isBlank()) {
            return "";
        }

        return cardNumber.replaceAll("\\D", "");
    }
